// merge-bot.mjs: the owner's rule, "Only if nothing visible changes", without a global lock (the owner, 2026-11-06:
// "Yes, build it"). Run by merge.yml (main's copy, never a PR's), one tick at a time; every tick, whatever woke it:
//   1. main's own gate is an alarm: red, the PR whose landing made it red is labelled broke-main and one issue opened.
//   2. LAND ON OWN GREEN. Every ready PR from a claude/* branch (not a draft, not labelled needs-owner or visible, not
//      changing the bot), lowest number first, whose gate on its head is green with frames identical, lands in this
//      tick when its base (the verdict's) is an ancestor of main and the files main changed since that base share no
//      area with the PR's (areas.json, the static area aside: main's own gate tests every merge after it lands).
//      Its head contains main: main is fast-forwarded to that exact commit. Else GitHub's merge API (sha = the tested
//      head; it refuses a conflict) merges it onto main. After each landing the next PR is checked against the new
//      main. Only a PR whose areas overlap main's changes (or that conflicts) is brought up to date and gated again.
//   3. THE DEPLOY GATE. Cloudflare serves the branch `live`. The bot fast-forwards it to the newest main tip M when
//      every main tip from live to M (first parent) has a green main gate, frames identical or the owner's own hand
//      merge (a PR labelled needs-owner or visible: his approval of what it shows), and no failed stall visits. Main
//      red: live stays, and the step summary names the culprit. Once M has the bake (tools/gpu/bake-stills.js), live
//      moves to M only with M's stills release up (its commit status `stills`, set by stills.yml; bot-rules.mjs). With no `live` yet, the bot makes it at the commit
//      https://derekzhou.com/build.txt names (what Cloudflare serves).
// It reverts only its own landing, and only after main's gate failed twice on it (step 1b): the owner's merges are his.
// Env: GITHUB_TOKEN (reads, labels, comments, issues), MERGE_TOKEN (landings, updates, live: a PAT, so its pushes run
//      the Gate), REPO (owner/name), DRY=1 (log what it would do, change nothing; MERGE_TOKEN not needed).
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { areasOf } from './areas.mjs';
import { walk, liveTarget } from './deploy-walk.mjs';
import { updateRefused, HOLD, botLanded, revertMessage, revertedTip, newestArtifact, stillsReady, rerunAnswer, proofHeads, reviewedIn } from './bot-rules.mjs';

const REPO = process.env.REPO, API = 'https://api.github.com/repos/' + REPO, DRY = process.env.DRY === '1';
const FOOT = '\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_';
const SELF = ['.github/workflows/merge.yml', '.github/ci/merge-bot.mjs'];
const say = (m) => console.log(m);
const summary = (m) => { say(m); if (process.env.GITHUB_STEP_SUMMARY) fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, m + '\n'); };
// fetch, tried again after 2, 4 and 8 s when the network fails (a connect timeout from the PC runner); an answer, a 4xx
// or a 5xx included, is returned as it is, never tried again
async function net(url, opts) {
  for (let i = 0; ; i++) {
    try { return await fetch(url, opts); }
    catch (e) { if (i === 3) throw e; say(`(network: ${e.cause?.code || e.message}; again in ${2 ** (i + 1)} s)`); await new Promise((r) => setTimeout(r, 2000 * 2 ** i)); }
  }
}
async function gh(method, p, body, token = process.env.GITHUB_TOKEN) {
  const r = await net(p.startsWith('http') ? p : API + p, { method, headers: { authorization: 'Bearer ' + token, accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28', 'user-agent': 'derekzhou.com-merge-bot' }, body: body ? JSON.stringify(body) : undefined });
  const t = await r.text(); let j = null; try { j = t ? JSON.parse(t) : null; } catch { j = t; }
  return { status: r.status, json: j };
}
const act = async (what, f) => { if (DRY) { say('(dry) ' + what); return { status: 0 }; } return f(); };
const label = async (n, name, color, description) => act(`label #${n} ${name}`, async () => {
  await gh('POST', '/labels', { name, color, description });
  await gh('POST', `/issues/${n}/labels`, { labels: [name] });
});

// The latest Gate run of a commit (any state), and its verdict artifact.
async function gateRun(sha) {
  const r = (await gh('GET', `/actions/workflows/gate.yml/runs?head_sha=${sha}&per_page=1`)).json;
  return r?.workflow_runs?.[0] || null;
}
// The gate-verdict artifact only, never the PC's copy (the hand-off's verdict-put): any PR's build code can write that
// folder, and GitHub scopes an artifact to its run (the hub's review of #321, 2026-11-16).
async function verdict(run) {
  const a = newestArtifact((await gh('GET', `/actions/runs/${run.id}/artifacts?name=gate-verdict&per_page=100`)).json?.artifacts);   // (a re-run's own, not its first attempt's)
  if (!a) return null;
  const r = await net(a.archive_download_url, { headers: { authorization: 'Bearer ' + process.env.GITHUB_TOKEN, 'user-agent': 'derekzhou.com-merge-bot' } });
  if (!r.ok) return null;
  const zip = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'verdict-')), 'v.zip');
  fs.writeFileSync(zip, Buffer.from(await r.arrayBuffer()));
  try { return JSON.parse(execFileSync('unzip', ['-p', zip, 'verdict.json'], { encoding: 'utf8' })); } catch { return null; }
}

if (!process.env.MERGE_TOKEN && !DRY) { say('::notice::MERGE_TOKEN is not set, so the merge bot is idle: nothing is merged, labelled or commented. The owner adds the repository secret MERGE_TOKEN to turn it on.'); process.exit(0); }

// 1. main's gate: an alarm.
let main = (await gh('GET', '/branches/main')).json?.commit?.sha;
if (!main) { say('cannot read main'); process.exit(1); }
const mrun = await gateRun(main);
const redIssues = ((await gh('GET', '/issues?state=open&labels=main-red&per_page=20')).json || []).filter((i) => !i.pull_request);
if (!mrun || mrun.status !== 'completed') say(`main ${main.slice(0, 10)}: its gate is ${mrun ? mrun.status : 'not started'}`);
else if (mrun.conclusion === 'success') {
  say(`main ${main.slice(0, 10)}: green`);
  for (const i of redIssues) await act(`close issue #${i.number}`, async () => {
    await gh('POST', `/issues/${i.number}/comments`, { body: `Main is green again at \`${main.slice(0, 10)}\` (${mrun.html_url}).${FOOT}` });
    await gh('PATCH', `/issues/${i.number}`, { state: 'closed', state_reason: 'completed' });
  });
} else if (mrun.conclusion !== 'cancelled' && mrun.conclusion !== 'skipped') {
  const culprit = ((await gh('GET', `/commits/${main}/pulls`)).json || []).find((p) => p.merged_at);
  say(`::warning::main ${main.slice(0, 10)} is red (${mrun.conclusion}${culprit ? ', after #' + culprit.number : ''})`);
  if (culprit && !(culprit.labels || []).some((l) => l.name === 'broke-main')) await label(culprit.number, 'broke-main', 'b60205', 'Main went red after this PR landed');
  const marker = `<!-- merge-train red ${main} -->`;
  if (!redIssues.some((i) => (i.body || '').includes(marker))) {
    const who = culprit ? `#${culprit.number} (${culprit.title})` : 'a commit with no PR';
    await act('open the main-red issue', async () => {
      await gh('POST', '/labels', { name: 'main-red', color: 'b60205', description: 'The gate failed on main' });
      await gh('POST', '/issues', { title: `Main is red after ${culprit ? '#' + culprit.number : main.slice(0, 10)}`, labels: ['main-red'], body: `${marker}\nThe gate failed on main at \`${main.slice(0, 10)}\`, which ${who} put there: ${mrun.html_url}\n\nThat commit is already live (Cloudflare deploys main in about 2.5 minutes, before the gate finishes). If the bot landed it, the bot re-runs the failed jobs once and, red again, reverts it itself (main goes back to the green tip before). The owner's own merge is his to revert: GitHub's **Revert** button on ${culprit ? '#' + culprit.number : 'the commit'}. Every PR the train lands is tested on top of main first, so a red main means something the PR's own gate did not see. This issue closes itself when main is green.${FOOT}` });
    });
  }
}

// 1b. AUTO-REVERT (the owner's hub, 2026-11-07): a red main after a bot landing is re-run once; red again, the bot
// lands the revert itself (bot-rules.mjs), and the PR's session hears of it on its PR.
if (mrun && mrun.status === 'completed' && mrun.conclusion === 'failure') {
  const c = (await gh('GET', `/commits/${main}`)).json;
  const n = botLanded(c?.commit?.message, (await gh('GET', `/commits/${main}/pulls`)).json, main);
  if (!n) say(`main ${main.slice(0, 10)}: red, but the bot did not land it (the owner's merge, or no PR): not reverted`);
  else if ((mrun.run_attempt || 1) < 2) {
    const r = await act(`re-run main's failed gate jobs (${mrun.id})`, () => gh('POST', `/actions/runs/${mrun.id}/rerun-failed-jobs`, {}, process.env.MERGE_TOKEN));
    if (DRY || r.status === 201) say(`main ${main.slice(0, 10)}: red after #${n}: its failed jobs run once more; red again, the bot reverts it`);
    else say(`::warning::main ${main.slice(0, 10)}: red after #${n}, and its gate could not be re-run (${r.status}: ${r.json?.message || ''}; MERGE_TOKEN needs Actions: write): not reverted, the owner looks`);
  } else {
    const v = await verdict(mrun), base = v?.base, brun = base && (await gateRun(base));
    if (!base || !brun || brun.conclusion !== 'success') say(`::warning::main ${main.slice(0, 10)}: red twice after #${n}, but the tip before it (${String(base).slice(0, 10)}) is not green either: not reverted, the owner looks`);
    else {
      const tree = (await gh('GET', `/git/commits/${base}`)).json?.tree?.sha;
      const k = tree && (await act(`commit the revert of #${n}`, () => gh('POST', '/git/commits', { message: revertMessage(n, main, base, mrun.html_url), tree, parents: [main] }, process.env.MERGE_TOKEN)));
      const sha = k?.json?.sha;
      const f = sha && (await gh('PATCH', '/git/refs/heads/main', { sha, force: false }, process.env.MERGE_TOKEN));
      if (f && f.status === 200) {
        summary(`auto-revert: main ${main.slice(0, 10)} was red twice after #${n}: main is now ${sha.slice(0, 10)} (the tree of ${base.slice(0, 10)})`);
        await act(`comment #${n}`, () => gh('POST', `/issues/${n}/comments`, { body: `**Reverted.** Main's gate failed twice after this landed (${mrun.html_url}), so the merge bot reverted it: main is \`${sha.slice(0, 10)}\`, the tree of \`${base.slice(0, 10)}\` (the green tip before). Fix it on a new branch from main and open a new PR.${FOOT}` }));
        main = sha;
      } else if (!DRY) say(`::warning::auto-revert of #${n} failed (${k?.status}/${f?.status}): ${k?.json?.message || f?.json?.message || ''}`);
    }
  }
}

// 2. the PRs, lowest number first.
const prs = ((await gh('GET', '/pulls?state=open&base=main&sort=created&direction=asc&per_page=100')).json || [])
  .filter((p) => p.head.ref.startsWith('claude/') && p.head.repo?.full_name === REPO && !p.draft)
  .sort((a, b) => a.number - b.number);
async function needsOwner(pr, sha, why, run) {
  const n = pr.number;
  say(`#${n}: needs the owner: ${why}`);
  const marker = `<!-- merge-bot ${sha} -->`;
  const comments = (await gh('GET', `/issues/${n}/comments?per_page=100`)).json || [];
  if (comments.some((c) => (c.body || '').includes(marker))) return;
  const checks = (await gh('GET', `/commits/${sha}/check-runs?per_page=100`)).json?.check_runs || [];
  const cf = checks.find((c) => c.name === 'Cloudflare Pages')?.output?.summary || '';
  const urls = [...cf.matchAll(/href='(https:\/\/[^']+\.pages\.dev)'/g)].map((m) => m[1]);
  const alias = 'https://' + pr.head.ref.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 28).replace(/-$/, '') + '.derekzhou.pages.dev';
  const preview = urls.length ? urls.map((u) => `<${u}>`).join(' (this commit) and ') + ' (the branch)' : `<${alias}> (the branch's preview; Cloudflare's own check has not reported yet)`;
  await label(n, 'needs-owner', 'd93f0b', 'The merge bot left this for the owner');
  await act(`comment #${n}`, () => gh('POST', `/issues/${n}/comments`, { body: `${marker}\n**Left for the owner** (\`${sha.slice(0, 10)}\`): ${why}.\n\nPreview: ${preview}${run ? `\n\nThe gate's run: ${run.html_url}` : ''}${FOOT}` }));
}
// The files a compare names (null when GitHub truncates the list: then nothing can be proved not to overlap).
async function compareFiles(a, b) {
  const c = (await gh('GET', `/compare/${a}...${b}?per_page=100`)).json;
  if (!c || !Array.isArray(c.files)) return { c, files: null };
  return { c, files: c.files.length >= 300 ? null : c.files.map((f) => f.filename) };
}
const areaSet = (files) => new Set(areasOf(files).areas.filter((a) => a !== 'static'));
async function updateBranch(pr, sha, why, run, files) {
  const n = pr.number;
  say(`#${n}: ${why}: bringing it up to date from main, its gate runs again`);
  const u = await act(`update #${n} from main`, () => gh('PUT', `/pulls/${n}/update-branch`, { expected_head_sha: sha }, process.env.MERGE_TOKEN));
  if (DRY || u.status === 202) await act(`comment #${n}`, () => gh('POST', `/issues/${n}/comments`, { body: `update needed: ${why}. The merge bot merged main (\`${main.slice(0, 10)}\`) into this branch; the gate runs again on top of it, and the bot lands it if it stays green. Pull before pushing again.${FOOT}` }));
  else if (!updateRefused(u.status).owner) {   // (a conflict: its session's to fix; no label, tried again every tick)
    say(`#${n}: conflicts with main (${u.status}): left to its session, tried again every tick`);
    const marker = `<!-- merge-bot conflict ${sha} -->`;
    const comments = (await gh('GET', `/issues/${n}/comments?per_page=100`)).json || [];
    if (!comments.some((c) => (c.body || '').includes(marker))) await act(`comment #${n}`, () => gh('POST', `/issues/${n}/comments`, { body: `${marker}\n**Conflicts with main** (\`${sha.slice(0, 10)}\`): ${why}, and GitHub cannot merge main into it (${u.status}: ${u.json?.message || u.json}). Merge main into the branch; the bot lands it once its gate is green. No label: nothing waits for the owner.${FOOT}` }));
  }
  else await needsOwner(pr, sha, `its branch could not be brought up to date with main (${u.status}: ${u.json?.message || u.json}); merge main into it, or MERGE_TOKEN needs Contents read/write${files.some((f) => f.startsWith('.github/workflows/')) ? ' and Workflows write' : ''}`, run);
}

const plan = [];   // (what this tick did or, dry, would do: one line a PR)
const dryLanded = [];   // (dry: the files of the PRs it would have merged, as if main held them)
for (const pr of prs) {
  const n = pr.number, sha = pr.head.sha, names = (pr.labels || []).map((l) => l.name);
  const note = (m) => { plan.push(`#${n}: ${m}`); say(`#${n}: ${m}`); };
  const approved = reviewedIn(pr.body, sha);   // (the hub's review of this very head: it lands visible or not, the bot's files included)
  const held = names.filter((x) => HOLD.includes(x));
  if (held.length && !approved) { note(`labelled ${held.join(', ')}: waits for the hub's review`); continue; }
  const files = [];
  for (let page = 1; page < 30; page++) { const r = (await gh('GET', `/pulls/${n}/files?per_page=100&page=${page}`)).json || []; files.push(...r.map((f) => f.filename)); if (r.length < 100) break; }
  if (!approved && files.some((f) => SELF.includes(f))) { note('changes the merge bot itself: waits for the hub\'s review'); continue; }
  const run = await gateRun(sha);
  if (!run) { note(`no gate run for ${sha.slice(0, 10)}: skipped`); continue; }
  if (run.status !== 'completed') { note(`its gate is ${run.status} on ${sha.slice(0, 10)}: waits for it`); continue; }
  if (run.conclusion === 'cancelled') { note('its gate was cancelled (a newer push): skipped'); continue; }
  const v = run.conclusion === 'success' ? await verdict(run) : null;
  if (!v || !v.gate_ok || v.sha !== sha) { note(`the gate is not green on ${sha.slice(0, 10)} (${run.conclusion}${v ? ', gate_ok ' + v.gate_ok : ', no verdict'}): skipped`); continue; }
  if (!v.frames_identical && !approved) { note(`frames may change (${v.reason}): waits for the hub's review`); continue; }
  if (v.t2 && v.t2.required && !v.t2.ran) { note('T2 was required and did not run: skipped'); continue; }
  if (v.t2 && v.t2.stall_ok === false) { note('its stall visits failed: skipped'); continue; }

  const cmp = (await gh('GET', `/compare/${main}...${sha}`)).json;
  if (!cmp || typeof cmp.behind_by !== 'number') { note('cannot compare with main: skipped'); continue; }
  let how;
  if (cmp.behind_by === 0) how = 'ff';   // (its tested head contains main: main moves to that very commit)
  else {
    // Its gate tested it on v.base. Main has moved since: does anything main changed share an area with the PR?
    const base = v.base;
    const anc = base ? (await gh('GET', `/compare/${base}...${main}`)).json : null;
    if (!anc || !['ahead', 'identical'].includes(anc.status)) { note(`its gate's base ${String(base).slice(0, 10)} is not an ancestor of main`); await updateBranch(pr, sha, 'its base is not on main', run, files); continue; }
    const mf = (await compareFiles(base, main)).files, mainFiles = mf && mf.concat(dryLanded), prFiles = (await compareFiles(base, sha)).files;
    if (!mainFiles || !prFiles) { note('too many files to compare'); await updateBranch(pr, sha, 'main moved and the change is too large to compare', run, files); continue; }
    const shared = [...areaSet(prFiles)].filter((a) => areaSet(mainFiles).has(a));
    const same = prFiles.filter((f) => mainFiles.includes(f));
    if (shared.length || same.length) { note(`main moved (${mainFiles.length} file(s)) and shares ${shared.length ? 'area ' + shared.join(', ') : 'files ' + same.slice(0, 5).join(', ')} with it: re-gated`); await updateBranch(pr, sha, `main moved and touched ${shared.length ? 'the ' + shared.join(', ') + ' area' : 'the same files'}`, run, files); continue; }
    how = 'merge';
  }
  note(`green on ${sha.slice(0, 10)}, ${approved ? 'the hub reviewed it' : `frames identical (${v.reason})`}: ${how === 'ff' ? 'lands as that exact commit' : 'merges onto main (main changed only other areas)'}`);
  if (DRY) { if (how === 'ff') main = sha; else dryLanded.push(...((await compareFiles(main, sha)).files || [])); continue; }
  if (how === 'ff') {
    const f = await gh('PATCH', '/git/refs/heads/main', { sha, force: false }, process.env.MERGE_TOKEN);
    if (f.status !== 200) { say(`#${n}: main could not be fast-forwarded (${f.status}: ${f.json?.message}): the next tick decides`); continue; }
    main = sha;
  } else {
    const m = await gh('PUT', `/pulls/${n}/merge`, { sha, merge_method: 'merge', commit_title: `Merge #${n}: ${pr.title}`.slice(0, 250) }, process.env.MERGE_TOKEN);
    if (m.status === 405 || m.status === 409) { await updateBranch(pr, sha, `it does not merge cleanly onto main (${m.json?.message})`, run, files); continue; }
    if (m.status !== 200) { await needsOwner(pr, sha, `the merge API refused it (${m.status}: ${m.json?.message}); MERGE_TOKEN needs Contents read/write${files.some((f) => f.startsWith('.github/workflows/')) ? ' and Workflows write' : ''}`, run); continue; }
    main = m.json.sha;
  }
  say(`landed #${n}: main is ${main}`);
  const after = (await gh('GET', `/pulls/${n}`)).json;
  if (!after?.merged) await act(`close #${n}`, async () => {
    await gh('POST', `/issues/${n}/comments`, { body: `Landed on main as \`${main}\` (main fast-forwarded to this PR's tested head).${FOOT}` });
    await gh('PATCH', `/pulls/${n}`, { state: 'closed' });
  });
}

// 3. the deploy gate: live follows main, a tested tip at a time.
// The owner's own merge: a PR labelled needs-owner or visible, or merged with GitHub's button (a merge commit "Merge pull
// request #N", which the bot never makes: it fast-forwards, or titles its merges "Merge #N: ...").
async function ownerMerge(sha) {
  const pulls = ((await gh('GET', `/commits/${sha}/pulls`)).json || []).filter((p) => p.merged_at);
  if (pulls.some((p) => (p.labels || []).some((l) => ['needs-owner', 'visible'].includes(l.name)))) return true;
  if (pulls.some((p) => reviewedIn(p.body, p.head.sha))) return true;   // (a PR the hub reviewed: the owner's rule of 2026-11-23)
  const c = (await gh('GET', `/commits/${sha}`)).json;
  return /^Merge pull request #\d+ /.test(c?.commit?.message || '') && (c?.parents || []).length === 2;
}
// A tip judged against something other than the main tip before it (main's gate before it compared with the push's
// `before`) is judged instead by its own branch's gate: the PR the bot fast-forwarded main to was frames-identical there.
// A tip the bot merged ("Merge #N: ...", two parents: main, then the PR's tested head) never had a branch gate of its
// own: the PR's gate on its head (the second parent) is the proof, as the bot judged it when it merged (2026-11-15: #258's
// merge 2715e19, its main gate cancelled, held live for 4 hours).
async function branchIdentical(sha) {
  const proved = async (h) => {
    const runs = ((await gh('GET', `/actions/workflows/gate.yml/runs?head_sha=${h}&per_page=20`)).json?.workflow_runs || []).filter((r) => r.head_branch !== 'main' && r.status === 'completed' && r.conclusion === 'success');
    for (const r of runs) { const v = await verdict(r); if (v && v.gate_ok && v.frames_identical && v.sha === h) return true; }
    return false;
  };
  if (await proved(sha)) return true;
  const c = (await gh('GET', `/commits/${sha}`)).json;
  for (const h of proofHeads(sha, c?.commit?.message, (c?.parents || []).map((p) => p.sha)).slice(1)) if (await proved(h)) return true;
  return false;
}
// A cancelled tip nothing proves: its own gate re-run, once, and only when every gate of main's is done (the walk's
// d.rerun; bot-rules.mjs rerunAnswer decides: 'rerun' asked now, 'wait', or 'again')
async function rerunTip(r, runs) {
  const a = rerunAnswer(r, runs);
  if (a !== 'rerun') return a;
  const x = await act(`re-run main ${r.head_sha.slice(0, 10)}'s cancelled gate (${r.id})`, () => gh('POST', `/actions/runs/${r.id}/rerun`, {}, process.env.MERGE_TOKEN));
  if (!DRY && x.status !== 201) { say(`::warning::main ${r.head_sha.slice(0, 10)}'s cancelled gate could not be re-run (${x.status}: ${x.json?.message || ''}; MERGE_TOKEN needs Actions: write)`); return null; }
  return 'rerun';
}
// The index of a later tip whose stall visits pass (-1: none). live may then pass the failed tip, but only as far as
// that later tip: stopping in between would serve bytes no passing stall visit measured.
async function laterStallOk(runs, r) {
  for (let i = runs.indexOf(r) + 1; i < runs.length; i++) {
    const x = runs[i];
    if (x.status !== 'completed' || x.conclusion !== 'success') continue;
    const w = await verdict(x);
    if (w && w.gate_ok && w.t2 && w.t2.ran && w.t2.stall_ok === true) return i;
  }
  return -1;
}
async function deployGate() {
  main = (await gh('GET', '/branches/main')).json?.commit?.sha || main;
  let live = (await gh('GET', '/branches/live')).json?.commit?.sha;
  if (!live) {
    const bt = await fetch('https://derekzhou.com/build.txt', { headers: { 'cache-control': 'no-cache', 'user-agent': 'derekzhou.com-merge-bot' } }).then((r) => (r.ok ? r.text() : '')).catch(() => '');
    const served = bt.trim();
    if (!/^[0-9a-f]{40}$/.test(served)) { summary(`deploy gate: no \`live\` branch, and /build.txt names no commit: nothing done`); return; }
    const a = (await gh('GET', `/compare/${served}...${main}`)).json;
    if (!a || !['ahead', 'identical'].includes(a.status)) { summary(`deploy gate: the served commit ${served.slice(0, 10)} is not on main: \`live\` not made`); return; }
    await act(`make live at ${served.slice(0, 10)}`, () => gh('POST', '/git/refs', { ref: 'refs/heads/live', sha: served }, process.env.MERGE_TOKEN));
    summary(`deploy gate: \`live\` made at the served commit ${served.slice(0, 10)}`); live = served;
  }
  if (live === main) { summary(`deploy gate: live is main (${main.slice(0, 10)})`); return; }
  const a = (await gh('GET', `/compare/${live}...${main}`)).json;
  if (!a || a.status !== 'ahead') { summary(`deploy gate: live ${live.slice(0, 10)} is not behind main (${a?.status}): nothing done`); return; }
  // main's tips since live: the push runs of the Gate on main whose commit lies between them, oldest first
  const between = new Set((a.commits || []).map((c) => c.sha));
  const runs = ((await gh('GET', '/actions/workflows/gate.yml/runs?branch=main&event=push&per_page=100')).json?.workflow_runs || [])
    .filter((r) => between.has(r.head_sha)).sort((x, y) => (a.commits.findIndex((c) => c.sha === x.head_sha) - a.commits.findIndex((c) => c.sha === y.head_sha)));
  if (!runs.some((r) => r.head_sha === main)) runs.push({ head_sha: main, status: 'queued', conclusion: null, html_url: '' });   // (main's tip, its gate not started yet: landed this tick)
  const revertOf = async (sha) => revertedTip((await gh('GET', `/commits/${sha}`)).json?.commit?.message);
  const prProved = async (sha, base) => {
    const rs = ((await gh('GET', `/actions/workflows/gate.yml/runs?head_sha=${sha}&per_page=20`)).json?.workflow_runs || []).filter((x) => x.head_branch !== 'main' && x.status === 'completed' && x.conclusion === 'success');
    for (const x of rs) { const w = await verdict(x); if (w && w.sha === sha && w.base === base && w.gate_ok && w.frames_identical && !(w.t2 && w.t2.required)) return true; }
    return false;
  };
  const w = await walk(live, runs, { verdict, ownerMerge, branchIdentical, laterStallOk, revertOf, prProved, rerun: rerunTip, say });
  if (w.why) summary('deploy gate: ' + w.why);
  // (the stills: a tip with the bake goes live only with its release up, bot-rules.mjs stillsReady; when the walk's
  // target has none yet, the newest walked tip that has: deploy-walk.mjs liveTarget)
  const ready = async (sha) => {
    const hasBake = (await gh('GET', `/contents/tools/gpu/bake-stills.js?ref=${sha}`)).status === 200;
    return stillsReady(hasBake, hasBake ? (await gh('GET', `/commits/${sha}/statuses?per_page=100`)).json : []);
  };
  const lt = await liveTarget(live, w.to, w.steps, ready), to = lt.to;
  if (lt.why) summary('deploy gate: ' + lt.why);
  if (to === live) { summary(`deploy gate: live stays at ${live.slice(0, 10)} (main ${main.slice(0, 10)})`); return; }
  const f = await act(`fast-forward live to ${to.slice(0, 10)}`, () => gh('PATCH', '/git/refs/heads/live', { sha: to, force: false }, process.env.MERGE_TOKEN));
  summary(DRY ? `deploy gate (dry): would move live ${live.slice(0, 10)} -> ${to.slice(0, 10)}` : f.status === 200 ? `deploy gate: live ${live.slice(0, 10)} -> ${to.slice(0, 10)}` : `deploy gate: live could not move (${f.status}: ${f.json?.message})`);
}
await deployGate();
if (plan.length) summary('\n' + (DRY ? '### What the bot would do\n' : '### What the bot did\n') + plan.map((l) => '- ' + l).join('\n'));
say('tick done');
